def transform(grid):
    # Propagate each nonzero diagonal stripe down-right, filling blank cells
    # when they are aligned with the original stripe.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            # A diagonal stripe is constant in r-c; source value must come
            # from the same diagonal, retaining the row's other patterns.
            for sr in range(r - 1, -1, -1):
                sc = c - (r - sr)
                if sc < 0:
                    continue
                if grid[sr][sc] != 0:
                    out[r][c] = grid[sr][sc]
                    break
    assert len(out) == h and all(len(row) == w for row in out)
    assert all(0 <= value <= 9 for row in out for value in row)
    return out

