def transform(grid):
    h, w = len(grid), len(grid[0])
    diag = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v:
                k = r-c
                if k in diag and diag[k] != v:
                    raise ValueError('mixed colors on a diagonal')
                diag[k] = v
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if r-c in diag:
                out[r][c] = diag[r-c]
    assert len(out) == h and all(len(row) == w for row in out)
    assert all(0 <= v <= 9 for row in out for v in row)
    return out
